  // TODO: create a private counter
}

function once(fn) {
  // TODO: return a function that runs fn only once
}

exercise.solution:
function createCounter(start = 0) {
  let count = start;

  return {
    increment() {
      count += 1;
      return count;
    },
    decrement() {
      count -= 1;
      return count;
    },
    value() {
      return count;
    }
  };
}

function once(fn) {
  let called = false;
  let result;

  return function (...args) {
    if (!called) {
      result = fn(...args);
      called = true;
    }

    return result;
  };
}
